-- Texas. The state had twenty-one stops, mostly sanitariums and ghost towns
-- from the original scan.
--
-- The best-sourced batch of the project: nps.gov, tpwd.texas.gov and
-- thc.texas.gov are the top three domains, with almost no aggregators.
--
-- One dropped — Cadillac Ranch was already here.
--
-- Two renamed for places that share a name with somewhere else: Big Bend's
-- Balanced Rock against Baraboo, Wisconsin's, and Nacogdoches' Old Stone Fort
-- against Schoharie, New York's. Both are real, neither is the other.
--
-- Texas spans two timezones, which no state so far has needed. El Paso and the
-- far west are Mountain; everywhere else is Central. The split is at roughly
-- -104.9, which catches El Paso and Hudspeth without catching Big Bend — Big
-- Bend is Central despite sitting further west than most people expect.
--
-- Eight proximity flags kept, all genuine: the Judge Roy Bean visitor centre
-- is fifteen metres from the Jersey Lilly saloon because the centre was built
-- around it, and the two Galveston naval museum ships are moored sixty metres
-- apart.
--
-- 205 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Slug Bug Ranch', 'slug-bug-ranch', 'roadside-oddities', 35.19322, -101.77164, 'Amarillo', 'TX', 'A tongue-in-cheek companion to Cadillac Ranch built from partially buried Volkswagen Beetles. The installation was relocated to Amarillo and remains a paint-friendly Route 66 photo stop.', 'open', 'https://www.visitamarillo.com/', null, 'America/Chicago', now()),
  ('U-Drop Inn and Tower Station', 'u-drop-inn-and-tower-station', 'weird-history', 35.22668, -100.24875, 'Shamrock', 'TX', 'A restored 1936 Art Deco gas station and cafe whose dramatic tower made it one of the most recognizable surviving Route 66 buildings in Texas.', 'open', 'https://www.shamrocktx.net/', null, 'America/Chicago', now()),
  ('Britten Leaning Water Tower', 'britten-leaning-water-tower', 'roadside-oddities', 35.20364, -101.10669, 'Groom', 'TX', 'A deliberately tilted water tower beside old Route 66, originally positioned at an angle to attract motorists. It remains one of the Panhandle''s classic roadside-photo stops.', 'roadside', 'https://www.visitamarillo.com/', null, 'America/Chicago', now()),
  ('Cross of Our Lord Jesus Christ', 'cross-of-our-lord-jesus-christ', 'roadside-oddities', 35.20543, -101.10538, 'Groom', 'TX', 'A 190-foot white cross rising over the plains beside I-40, surrounded by bronze Stations of the Cross and other religious sculptures.', 'open', 'https://crossministries.net/', null, 'America/Chicago', now()),
  ('Devil''s Rope Museum', 'devils-rope-museum', 'museums', 35.23166, -100.59675, 'McLean', 'TX', 'A museum devoted largely to barbed wire, fencing patents, tools, ranching history and Route 66 artifacts. Its thousands of wire samples make it unusually specific even by roadside-museum standards.', 'open', 'https://www.barbwiremuseum.com/', null, 'America/Chicago', now()),
  ('Phillips 66 Station', 'phillips-66-station', 'weird-history', 35.2336, -100.59946, 'McLean', 'TX', 'A tiny restored 1929 Phillips 66 station representing the earliest standardized cottage-style stations used by the company along historic highways.', 'roadside', 'https://www.visitamarillo.com/', null, 'America/Chicago', now()),
  ('Pioneer West Museum', 'pioneer-west-museum', 'weird-history', 35.21438, -100.24942, 'Shamrock', 'TX', 'A local-history museum inside a former hotel with pioneer, ranching and Route 66 material from the eastern Texas Panhandle.', 'open', 'https://www.shamrocktx.net/', null, 'America/Chicago', now()),
  ('Glenrio Ghost Town', 'glenrio-ghost-town', 'weird-history', 35.1789, -103.04269, 'Glenrio', 'TX', 'A near-abandoned Route 66 settlement straddling the Texas-New Mexico line. Remains of motels, service stations and road businesses survive as a stark reminder of traffic shifting to the interstate.', 'roadside', 'https://www.nps.gov/places/glenrio-historic-district.htm', null, 'America/Chicago', now()),
  ('Tex Randall', 'tex-randall', 'roadside-oddities', 34.98508, -101.92422, 'Canyon', 'TX', 'A towering cowboy statue built in the 1950s to advertise a western store. Restored after decades of weather damage, he remains one of the Panhandle''s best roadside giants.', 'roadside', 'https://www.visitamarillo.com/', null, 'America/Chicago', now()),
  ('Palo Duro Canyon Lighthouse Rock', 'palo-duro-canyon-lighthouse-rock', 'roadside-oddities', 34.94973, -101.67088, 'Canyon', 'TX', 'The park''s signature hoodoo resembles a stone lighthouse rising from the canyon floor. It is reached by the Lighthouse Trail and is one of the most distinctive natural formations in the Panhandle.', 'open', 'https://tpwd.texas.gov/state-parks/palo-duro-canyon', null, 'America/Chicago', now()),
  ('Palo Duro Canyon Cowboy Dugout', 'palo-duro-canyon-cowboy-dugout', 'weird-history', 34.9577, -101.6722, 'Canyon', 'TX', 'A reconstructed frontier dugout showing the partly underground shelter style used by early ranchers and settlers in the canyon country.', 'open', 'https://tpwd.texas.gov/state-parks/palo-duro-canyon', null, 'America/Chicago', now()),
  ('Alibates Flint Quarries National Monument', 'alibates-flint-quarries-national-monument', 'weird-history', 35.5817, -101.7052, 'Fritch', 'TX', 'Prehistoric quarry pits where Native peoples extracted colorful Alibates flint for thousands of years. Access to the quarry areas is generally by ranger-led tour.', 'limited', 'https://www.nps.gov/alfl/', null, 'America/Chicago', now()),
  ('Adobe Walls Battle Site', 'adobe-walls-battle-site', 'weird-history', 35.8937, -101.3295, 'Stinnett', 'TX', 'The isolated Panhandle site of the 1874 Second Battle of Adobe Walls, where buffalo hunters and Native warriors fought near a frontier trading post.', 'roadside', 'https://www.thc.texas.gov/', null, 'America/Chicago', now()),
  ('Old Mobeetie Jail Museum', 'old-mobeetie-jail-museum', 'museums', 35.53682, -100.43888, 'Mobeetie', 'TX', 'A preserved 1886 sandstone jail that now interprets Old Mobeetie''s frontier-boomtown history, lawmen, outlaws and military connections.', 'open', 'https://www.mobeetie.com/', null, 'America/Chicago', now()),
  ('Panhandle-Plains Historical Museum', 'panhandle-plains-historical-museum', 'weird-history', 34.98039, -101.91667, 'Canyon', 'TX', 'A huge regional museum with fossil material, Plains cultures, oil-boom artifacts, historic vehicles, firearms and recreated streetscapes spanning Texas Panhandle history.', 'open', 'https://www.panhandleplains.org/', null, 'America/Chicago', now()),
  ('American Quarter Horse Hall of Fame & Museum', 'american-quarter-horse-hall-of-fame-museum', 'museums', 35.19464, -101.80577, 'Amarillo', 'TX', 'A museum dedicated to the American Quarter Horse, including breed history, legendary horses and riders, trophies and western material culture.', 'open', 'https://www.aqha.com/museum', null, 'America/Chicago', now()),
  ('Jack Sisemore Traveland RV Museum', 'jack-sisemore-traveland-rv-museum', 'museums', 35.15531, -101.91818, 'Amarillo', 'TX', 'A private collection of vintage recreational vehicles, motorcycles and road-trip memorabilia preserving the design history of American camping and highway travel.', 'limited', 'https://www.rvmuseum.net/', null, 'America/Chicago', now()),
  ('Bill''s Backyard Classics', 'bills-backyard-classics', 'museums', 35.17256, -101.92303, 'Amarillo', 'TX', 'A large privately assembled collection of classic and custom automobiles with an old-garage atmosphere and a rotating mix of unusual vehicles.', 'open', 'https://www.billsbackyardclassics.com/', null, 'America/Chicago', now()),
  ('Kwahadi Museum of the American Indian', 'kwahadi-museum-of-the-american-indian', 'folklore', 35.19738, -101.75489, 'Amarillo', 'TX', 'A distinctive pueblo-style museum and performance space interpreting Indigenous art, regalia and traditions of the Southwest and Plains.', 'limited', 'https://www.kwahadi.com/', null, 'America/Chicago', now()),
  ('Marfa Lights Viewing Area', 'marfa-lights-viewing-area', 'haunted', 30.27516, -103.88279, 'Marfa', 'TX', 'The official roadside viewing area for the unexplained Marfa Lights, glowing points reported for generations across Mitchell Flat east of town.', 'open', 'https://visitmarfa.com/mystery', null, 'America/Chicago', now()),
  ('Prada Marfa', 'prada-marfa', 'roadside-oddities', 30.60346, -104.51851, 'Valentine', 'TX', 'A permanently sealed faux Prada storefront standing alone in the West Texas desert. The installation is both minimalist art and one of the state''s most surreal roadside scenes.', 'roadside', 'https://ballroommarfa.org/prada-marfa/', null, 'America/Chicago', now()),
  ('Chinati Foundation', 'chinati-foundation', 'museums', 30.30371, -104.02148, 'Marfa', 'TX', 'Donald Judd''s large-scale contemporary art museum occupies a former military base and spreads minimalist installations across buildings and desert grounds.', 'open', 'https://chinati.org/', null, 'America/Chicago', now()),
  ('Judd Foundation Marfa', 'judd-foundation-marfa', 'museums', 30.31039, -104.02078, 'Marfa', 'TX', 'Preserved living and working spaces used by artist Donald Judd, including architecture, furniture and permanently installed artworks viewed on guided tours.', 'limited', 'https://juddfoundation.org/', null, 'America/Chicago', now()),
  ('Blackwell School National Historic Site', 'blackwell-school-national-historic-site', 'weird-history', 30.30654, -104.02124, 'Marfa', 'TX', 'A preserved school documenting the segregated education of Mexican American children in Marfa and the community history surrounding it.', 'open', 'https://www.nps.gov/blsc/', null, 'America/Chicago', now()),
  ('Terlingua Ghost Town', 'terlingua-ghost-town', 'weird-history', 29.3212, -103.61656, 'Terlingua', 'TX', 'Ruins of the Chisos Mining Company settlement remain scattered around modern Terlingua, including stone walls, mine-era structures and desert streets.', 'open', 'https://www.ghosttowntexas.com/', null, 'America/Chicago', now()),
  ('Terlingua Cemetery', 'terlingua-cemetery', 'weird-history', 29.31921, -103.61229, 'Terlingua', 'TX', 'A weathered desert cemetery filled with hand-built graves, wooden crosses and mining-era burials. It is especially associated with Terlingua''s Day of the Dead traditions.', 'open', 'https://www.ghosttowntexas.com/', null, 'America/Chicago', now()),
  ('Chisos Mining Company Ruins', 'chisos-mining-company-ruins', 'weird-history', 29.32204, -103.61601, 'Terlingua', 'TX', 'Stone and concrete remains from the quicksilver-mining operation that created the original Terlingua settlement.', 'open', 'https://www.ghosttowntexas.com/', null, 'America/Chicago', now()),
  ('Perry Mansion', 'perry-mansion', 'weird-history', 29.32171, -103.61458, 'Terlingua', 'TX', 'The crumbling desert residence of mining entrepreneur Howard E. Perry overlooks the former company town and survives as one of Terlingua''s most recognizable ruins.', 'roadside', 'https://www.ghosttowntexas.com/', null, 'America/Chicago', now()),
  ('Hot Springs Historic District', 'hot-springs-historic-district', 'weird-history', 29.17925, -102.99946, 'Big Bend National Park', 'TX', 'Ruins of a riverfront health resort surround a geothermal spring beside the Rio Grande. The site also preserves pictographs and traces of early settlement.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/hot-springs.htm', null, 'America/Chicago', now()),
  ('Hot Springs Pictographs', 'hot-springs-pictographs', 'weird-history', 29.17966, -103.00009, 'Big Bend National Park', 'TX', 'Small prehistoric pictographs survive on the limestone wall along the Hot Springs trail, one of only two prehistoric sites in Big Bend specifically managed for routine public visitation.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/archaeology-in-big-bend.htm', null, 'America/Chicago', now()),
  ('The Chimneys Rock Art', 'the-chimneys-rock-art', 'weird-history', 29.24612, -103.46286, 'Big Bend National Park', 'TX', 'Volcanic rock spires along the Chimneys Trail contain Native American petroglyphs and evidence of long human use in the Chihuahuan Desert.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/archaeology-in-big-bend.htm', null, 'America/Chicago', now()),
  ('Homer Wilson Ranch', 'homer-wilson-ranch', 'weird-history', 29.23009, -103.37835, 'Big Bend National Park', 'TX', 'A lonely stone ranch house in the Blue Creek valley survives from one of the region''s large early-20th-century ranching operations.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/homer-wilson-ranch.htm', null, 'America/Chicago', now()),
  ('Castolon Historic District', 'castolon-historic-district', 'weird-history', 29.13704, -103.51019, 'Big Bend National Park', 'TX', 'A remote former military, farming and trading settlement along the Rio Grande with historic adobe and stone structures.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/castolon.htm', null, 'America/Chicago', now()),
  ('Sam Nail Ranch', 'sam-nail-ranch', 'weird-history', 29.28976, -103.3747, 'Big Bend National Park', 'TX', 'Ruins and surviving windmill equipment mark a small homestead where desert settlers attempted to farm and ranch in the early 1900s.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/sam-nail-ranch.htm', null, 'America/Chicago', now()),
  ('Mariscal Mine', 'mariscal-mine', 'weird-history', 29.09438, -103.18196, 'Big Bend National Park', 'TX', 'Remote ruins of a mercury mine and processing complex stand on the desert slopes, preserving furnaces, foundations and dangerous mining history.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/mariscal-mine.htm', null, 'America/Chicago', now()),
  ('Luna''s Jacal', 'lunas-jacal', 'weird-history', 29.24261, -103.56855, 'Big Bend National Park', 'TX', 'A tiny stone-and-wood shelter traditionally associated with Gilberto Luna, who lived in the remote desert country for decades.', 'open', 'https://www.nps.gov/bibe/learn/historyculture/lunas-jacal.htm', null, 'America/Chicago', now()),
  ('Ernst Tinaja', 'ernst-tinaja', 'roadside-oddities', 29.21893, -102.94323, 'Big Bend National Park', 'TX', 'A dramatic natural rock basin carved into colorful limestone in a remote canyon. High-clearance access and desert-road conditions make the visit limited.', 'limited', 'https://www.nps.gov/bibe/', null, 'America/Chicago', now()),
  ('Balanced Rock', 'balanced-rock-big-bend', 'roadside-oddities', 29.25283, -103.26806, 'Big Bend National Park', 'TX', 'A huge boulder improbably wedged between rock towers at the end of the Grapevine Hills Trail.', 'open', 'https://www.nps.gov/bibe/', null, 'America/Chicago', now()),
  ('Fossil Discovery Exhibit', 'fossil-discovery-exhibit', 'museums', 29.33164, -103.22848, 'Big Bend National Park', 'TX', 'An open-air exhibit interprets Big Bend''s extraordinary fossil record, including giant crocodilians, dinosaurs and early mammals from multiple geologic periods.', 'open', 'https://www.nps.gov/bibe/planyourvisit/fossil-discovery-exhibit.htm', null, 'America/Chicago', now()),
  ('Fort Leaton State Historic Site', 'fort-leaton-state-historic-site', 'weird-history', 29.55992, -104.37154, 'Presidio', 'TX', 'A massive fortified adobe trading post along the Rio Grande, reconstructed to show the isolated borderland world of the 1800s.', 'open', 'https://tpwd.texas.gov/state-parks/fort-leaton', null, 'America/Chicago', now()),
  ('Shafter Ghost Town', 'shafter-ghost-town', 'weird-history', 29.81936, -104.3041, 'Shafter', 'TX', 'Abandoned silver-mining buildings, ruins and a small cemetery survive in this near-empty Presidio County settlement. Much of the surrounding land is private.', 'roadside', 'https://visitbigbend.com/', null, 'America/Chicago', now()),
  ('Museum of the Big Bend', 'museum-of-the-big-bend', 'museums', 30.3631, -103.65021, 'Alpine', 'TX', 'A museum at Sul Ross State University covering Big Bend archaeology, maps, Indigenous cultures, ranching and borderlands history.', 'open', 'https://www.museumofthebigbend.com/', null, 'America/Chicago', now()),
  ('Rattlers & Reptiles', 'rattlers-reptiles', 'museums', 30.58883, -103.89498, 'Fort Davis', 'TX', 'A small roadside reptile museum displaying live venomous snakes and other desert reptiles from the Southwest.', 'open', 'https://visitfortdavis.com/', null, 'America/Chicago', now()),
  ('Fort Davis National Historic Site', 'fort-davis-national-historic-site', 'weird-history', 30.5978, -103.89573, 'Fort Davis', 'TX', 'One of the best-preserved frontier military posts in the Southwest, with restored barracks, officers'' quarters and ruins set beneath dramatic cliffs.', 'open', 'https://www.nps.gov/foda/', null, 'America/Chicago', now()),
  ('McDonald Observatory', 'mcdonald-observatory', 'roadside-oddities', 30.6716, -104.02268, 'Fort Davis', 'TX', 'A major astronomical observatory high in the Davis Mountains, known for giant research telescopes, star parties and unusually dark skies.', 'limited', 'https://mcdonaldobservatory.org/', null, 'America/Chicago', now()),
  ('Odessa Meteor Crater', 'odessa-meteor-crater', 'roadside-oddities', 31.7571, -102.47827, 'Odessa', 'TX', 'A broad, shallow impact crater complex created by an iron meteorite. A small museum and trail explain the impact and the site''s scientific history.', 'open', 'https://www.odessameteorcrater.com/', null, 'America/Chicago', now()),
  ('Stonehenge Replica at UTPB', 'stonehenge-replica-at-utpb', 'roadside-oddities', 31.89016, -102.32991, 'Odessa', 'TX', 'A full-size horizontal-dimension replica of Stonehenge built from massive limestone blocks on the University of Texas Permian Basin campus.', 'open', 'https://www.utpb.edu/', null, 'America/Chicago', now()),
  ('Jack Ben Rabbit Statue', 'jack-ben-rabbit-statue', 'roadside-oddities', 31.84808, -102.36766, 'Odessa', 'TX', 'A giant jackrabbit statue celebrating the long-running local jackrabbit-roping legend and Odessa''s fondness for oversized public art.', 'roadside', 'https://www.discoverodessa.org/', null, 'America/Chicago', now()),
  ('Permian Basin Petroleum Museum', 'permian-basin-petroleum-museum', 'museums', 31.97216, -102.09067, 'Midland', 'TX', 'A museum devoted to oil geology, drilling technology and the petroleum boom, with historic rigs and machinery spread across indoor and outdoor exhibits.', 'open', 'https://petroleummuseum.org/', null, 'America/Chicago', now()),
  ('Million Barrel Museum', 'million-barrel-museum', 'weird-history', 31.59342, -102.89208, 'Monahans', 'TX', 'A gigantic concrete oil-storage tank built in the 1920s forms the centerpiece of a local-history complex devoted to the Permian Basin oil boom.', 'open', 'https://www.cityofmonahans.org/', null, 'America/Chicago', now()),
  ('Paisano Pete', 'paisano-pete', 'roadside-oddities', 30.88955, -102.87989, 'Fort Stockton', 'TX', 'A giant roadrunner statue that has become Fort Stockton''s signature roadside mascot.', 'roadside', 'https://www.fortstockton.org/', null, 'America/Chicago', now()),
  ('Historic Fort Stockton', 'historic-fort-stockton', 'weird-history', 30.8874, -102.87938, 'Fort Stockton', 'TX', 'Preserved frontier-army buildings and reconstructed structures interpret the post that protected travelers and regional settlements after the Civil War.', 'open', 'https://www.historicfortstockton.org/', null, 'America/Chicago', now()),
  ('Annie Riggs Memorial Museum', 'annie-riggs-memorial-museum', 'weird-history', 30.8855, -102.87967, 'Fort Stockton', 'TX', 'A former frontier hotel now packed with local artifacts, period rooms and stories from Pecos County''s military, ranching and pioneer past.', 'open', 'https://www.annieriggs.com/', null, 'America/Chicago', now()),
  ('Museum of the Weird', 'museum-of-the-weird', 'museums', 30.26705, -97.73874, 'Austin', 'TX', 'A classic dime-museum-style attraction filled with cryptids, sideshow material, odd taxidermy, movie props and other curiosities.', 'open', 'https://www.museumoftheweird.com/', null, 'America/Chicago', now()),
  ('Cathedral of Junk', 'cathedral-of-junk', 'roadside-oddities', 30.22687, -97.77162, 'Austin', 'TX', 'A towering backyard environment built from bicycles, electronics, bottles, signs and other discarded objects. Visits are by arrangement because it remains on private residential property.', 'limited', 'https://www.austintexas.org/', null, 'America/Chicago', now()),
  ('Elisabet Ney Museum', 'elisabet-ney-museum', 'museums', 30.30737, -97.7261, 'Austin', 'TX', 'The castle-like former studio of sculptor Elisabet Ney preserves monumental statues, plaster models and the strange domestic-workspace atmosphere of her Austin years.', 'open', 'https://www.austintexas.gov/department/elisabet-ney-museum', null, 'America/Chicago', now()),
  ('Texas Science & Natural History Museum', 'texas-science-natural-history-museum', 'museums', 30.28622, -97.73217, 'Austin', 'TX', 'The University of Texas natural-history museum displays Texas fossils, dinosaurs, meteorites and geological specimens.', 'open', 'https://sciencemuseum.utexas.edu/', null, 'America/Chicago', now()),
  ('Treaty Oak', 'treaty-oak', 'folklore', 30.27258, -97.75015, 'Austin', 'TX', 'An ancient live oak wrapped in Texas folklore, including stories connecting it with Native councils and Stephen F. Austin. The tree survived a deliberate poisoning in 1989.', 'open', 'https://www.austintexas.gov/', null, 'America/Chicago', now()),
  ('Austin Moonlight Tower at Zilker Park', 'austin-moonlight-tower-at-zilker-park', 'roadside-oddities', 30.26674, -97.76855, 'Austin', 'TX', 'One of Austin''s surviving 19th-century moonlight towers, an obsolete citywide lighting technology preserved as a distinctive part of the urban landscape.', 'roadside', 'https://www.austintexas.gov/', null, 'America/Chicago', now()),
  ('Nightwing Bat Sculpture', 'nightwing-bat-sculpture', 'roadside-oddities', 30.26091, -97.74492, 'Austin', 'TX', 'A giant stylized bat sculpture at the Congress Avenue bridge honors the enormous Mexican free-tailed bat colony that emerges from beneath the bridge.', 'roadside', 'https://www.austintexas.org/', null, 'America/Chicago', now()),
  ('Congress Avenue Bridge Bat Colony', 'congress-avenue-bridge-bat-colony', 'roadside-oddities', 30.26164, -97.74528, 'Austin', 'TX', 'The bridge houses one of the world''s largest urban bat colonies. On warm-season evenings, huge streams of bats emerge at dusk.', 'limited', 'https://www.austintexas.org/things-to-do/outdoors/bat-watching/', null, 'America/Chicago', now()),
  ('Oakwood Cemetery', 'oakwood-cemetery', 'weird-history', 30.27627, -97.72505, 'Austin', 'TX', 'Austin''s oldest city cemetery contains elaborate monuments, early Texas figures and layers of local death history.', 'open', 'https://www.austintexas.gov/oakwoodcemetery', null, 'America/Chicago', now()),
  ('Texas State Cemetery', 'texas-state-cemetery', 'weird-history', 30.26529, -97.7279, 'Austin', 'TX', 'A landscaped state cemetery holding governors, legislators, soldiers and notable Texans, with monuments ranging from restrained markers to elaborate memorials.', 'open', 'https://cemetery.tspb.texas.gov/', null, 'America/Chicago', now()),
  ('Dead Man''s Hole', 'dead-mans-hole', 'weird-history', 30.59452, -98.21453, 'Marble Falls', 'TX', 'A deep natural sinkhole associated with Civil War-era killings and local legends. A historical marker explains the grim history beside the fenced opening.', 'roadside', 'https://www.thc.texas.gov/', null, 'America/Chicago', now()),
  ('Longhorn Cavern State Park', 'longhorn-cavern-state-park', 'roadside-oddities', 30.68444, -98.35097, 'Burnet', 'TX', 'A long limestone cavern sculpted by ancient underground water, layered with outlaw, dance-hall, wartime and Civilian Conservation Corps stories.', 'open', 'https://tpwd.texas.gov/state-parks/longhorn-cavern/', null, 'America/Chicago', now()),
  ('Devil''s Waterhole', 'devils-waterhole', 'roadside-oddities', 30.74684, -98.37108, 'Burnet', 'TX', 'A deep, narrow swimming hole framed by pink granite at Inks Lake State Park, reached by a short trail through exposed rock.', 'open', 'https://tpwd.texas.gov/state-parks/inks-lake', null, 'America/Chicago', now()),
  ('Enchanted Rock', 'enchanted-rock', 'folklore', 30.50634, -98.81873, 'Fredericksburg', 'TX', 'A gigantic pink-granite dome tied to Indigenous stories, strange nighttime sounds and generations of Texas folklore.', 'open', 'https://tpwd.texas.gov/state-parks/enchanted-rock', null, 'America/Chicago', now()),
  ('Old Tunnel State Park Bat Colony', 'old-tunnel-state-park-bat-colony', 'roadside-oddities', 30.10118, -98.82087, 'Fredericksburg', 'TX', 'An abandoned railroad tunnel now shelters millions of Mexican free-tailed bats and cave myotis, producing huge seasonal evening emergences.', 'limited', 'https://tpwd.texas.gov/state-parks/old-tunnel', null, 'America/Chicago', now()),
  ('Stonehenge II', 'stonehenge-ii', 'roadside-oddities', 30.07976, -99.23954, 'Ingram', 'TX', 'A Texas Hill Country replica of Stonehenge, accompanied by large Easter Island-style heads, now preserved on the grounds of the Hill Country Arts Foundation.', 'open', 'https://hcaf.com/stonehenge-ii/', null, 'America/Chicago', now()),
  ('Cave Without a Name', 'cave-without-a-name', 'roadside-oddities', 29.9493, -98.69372, 'Boerne', 'TX', 'A decorated show cave whose unusual name came from a 1939 contest winner who said the cavern was too beautiful to have a name.', 'open', 'https://www.cavewithoutaname.com/', null, 'America/Chicago', now()),
  ('Cascade Caverns', 'cascade-caverns', 'roadside-oddities', 29.73541, -98.6989, 'Boerne', 'TX', 'A historic Hill Country show cave with guided tours through limestone chambers, formations and a deep underground room.', 'open', 'https://cascadecaverns.com/', null, 'America/Chicago', now()),
  ('Natural Bridge Caverns', 'natural-bridge-caverns', 'roadside-oddities', 29.69248, -98.34283, 'San Antonio', 'TX', 'Texas'' largest commercial cavern attraction, with vast chambers, active formations and multiple developed underground tour routes.', 'open', 'https://www.naturalbridgecaverns.com/', null, 'America/Chicago', now()),
